module axis_async_fifo_adapter #
(
    parameter DEPTH = 4096,
    parameter S_DATA_WIDTH = 8,
    parameter S_KEEP_ENABLE = (S_DATA_WIDTH>8),
    parameter S_KEEP_WIDTH = ((S_DATA_WIDTH+7)/8),
    parameter M_DATA_WIDTH = 8,
    parameter M_KEEP_ENABLE = (M_DATA_WIDTH>8),
    parameter M_KEEP_WIDTH = ((M_DATA_WIDTH+7)/8),
    parameter ID_ENABLE = 0,
    parameter ID_WIDTH = 8,
    parameter DEST_ENABLE = 0,
    parameter DEST_WIDTH = 8,
    parameter USER_ENABLE = 1,
    parameter USER_WIDTH = 1,
    parameter RAM_PIPELINE = 1,
    parameter OUTPUT_FIFO_ENABLE = 0,
    parameter FRAME_FIFO = 0,
    parameter USER_BAD_FRAME_VALUE = 1'b1,
    parameter USER_BAD_FRAME_MASK = 1'b1,
    parameter DROP_OVERSIZE_FRAME = FRAME_FIFO,
    parameter DROP_BAD_FRAME = 0,
    parameter DROP_WHEN_FULL = 0,
    parameter MARK_WHEN_FULL = 0,
    parameter PAUSE_ENABLE = 0,
    parameter FRAME_PAUSE = FRAME_FIFO
)
(
    /*
     * AXI input
     */
    input  wire                     s_clk,
    input  wire                     s_rst,
    input  wire [S_DATA_WIDTH-1:0]  s_axis_tdata,
    input  wire [S_KEEP_WIDTH-1:0]  s_axis_tkeep,
    input  wire                     s_axis_tvalid,
    output wire                     s_axis_tready,
    input  wire                     s_axis_tlast,
    input  wire [ID_WIDTH-1:0]      s_axis_tid,
    input  wire [DEST_WIDTH-1:0]    s_axis_tdest,
    input  wire [USER_WIDTH-1:0]    s_axis_tuser,
    /*
     * AXI output
     */
    input  wire                     m_clk,
    input  wire                     m_rst,
    output wire [M_DATA_WIDTH-1:0]  m_axis_tdata,
    output wire [M_KEEP_WIDTH-1:0]  m_axis_tkeep,
    output wire                     m_axis_tvalid,
    input  wire                     m_axis_tready,
    output wire                     m_axis_tlast,
    output wire [ID_WIDTH-1:0]      m_axis_tid,
    output wire [DEST_WIDTH-1:0]    m_axis_tdest,
    output wire [USER_WIDTH-1:0]    m_axis_tuser,
    /*
     * Pause
     */
    input  wire                     s_pause_req,
    output wire                     s_pause_ack,
    input  wire                     m_pause_req,
    output wire                     m_pause_ack,
    /*
     * Status
     */
    output wire [$clog2(DEPTH):0]   s_status_depth,
    output wire [$clog2(DEPTH):0]   s_status_depth_commit,
    output wire                     s_status_overflow,
    output wire                     s_status_bad_frame,
    output wire                     s_status_good_frame,
    output wire [$clog2(DEPTH):0]   m_status_depth,
    output wire [$clog2(DEPTH):0]   m_status_depth_commit,
    output wire                     m_status_overflow,
    output wire                     m_status_bad_frame,
    output wire                     m_status_good_frame
);

    localparam ADDR_WIDTH = $clog2(DEPTH);
    localparam PTR_WIDTH = ADDR_WIDTH + 1;
    localparam DEPTH_MASK = DEPTH - 1;

    // Internal signals
    wire s_wr_en;
    wire m_rd_en;
    wire s_full;
    wire m_empty;
    wire s_overflow;
    wire m_overflow;
    wire s_bad_frame;
    wire m_bad_frame;
    wire s_good_frame;
    wire m_good_frame;
    wire s_pause;
    wire m_pause;
    wire s_pause_active;
    wire m_pause_active;

    // Width adapter internal signals
    wire [S_DATA_WIDTH-1:0] s_data_to_fifo;
    wire [S_KEEP_WIDTH-1:0] s_keep_to_fifo;
    wire s_tlast_to_fifo;
    wire [ID_WIDTH-1:0] s_tid_to_fifo;
    wire [DEST_WIDTH-1:0] s_tdest_to_fifo;
    wire [USER_WIDTH-1:0] s_tuser_to_fifo;

    // FIFO output (in S domain)
    wire [S_DATA_WIDTH-1:0] fifo_out_data;
    wire [S_KEEP_WIDTH-1:0] fifo_out_keep;
    wire fifo_out_tlast;
    wire [ID_WIDTH-1:0] fifo_out_tid;
    wire [DEST_WIDTH-1:0] fifo_out_tdest;
    wire [USER_WIDTH-1:0] fifo_out_tuser;

    // Width adapter output (in M domain)
    wire [M_DATA_WIDTH-1:0] m_data_out;
    wire [M_KEEP_WIDTH-1:0] m_keep_out;
    wire m_tlast_out;
    wire [ID_WIDTH-1:0] m_tid_out;
    wire [DEST_WIDTH-1:0] m_tdest_out;
    wire [USER_WIDTH-1:0] m_tuser_out;
    wire m_valid_out;
    wire m_ready_in;

    // Assign outputs
    assign m_axis_tdata = m_data_out;
    assign m_axis_tkeep = M_KEEP_ENABLE ? m_keep_out : {M_KEEP_WIDTH{1'b0}};
    assign m_axis_tvalid = m_valid_out;
    assign m_axis_tlast = m_tlast_out;
    assign m_axis_tid = ID_ENABLE ? m_tid_out : {ID_WIDTH{1'b0}};
    assign m_axis_tdest = DEST_ENABLE ? m_tdest_out : {DEST_WIDTH{1'b0}};
    assign m_axis_tuser = USER_ENABLE ? m_tuser_out : {USER_WIDTH{1'b0}};

    assign s_axis_tready = s_wr_en;
    assign s_pause_ack = s_pause_active;
    assign m_pause_ack = m_pause_active;

    // Status signals
    wire [$clog2(DEPTH):0] s_depth;
    wire [$clog2(DEPTH):0] m_depth;
    wire [$clog2(DEPTH):0] s_depth_commit;
    wire [$clog2(DEPTH):0] m_depth_commit;

    assign s_status_depth = s_depth;
    assign s_status_depth_commit = s_depth_commit;
    assign s_status_overflow = s_overflow;
    assign s_status_bad_frame = s_bad_frame;
    assign s_status_good_frame = s_good_frame;
    assign m_status_depth = m_depth;
    assign m_status_depth_commit = m_depth_commit;
    assign m_status_overflow = m_overflow;
    assign m_status_bad_frame = m_bad_frame;
    assign m_status_good_frame = m_good_frame;

    // Pause logic
    assign s_pause = PAUSE_ENABLE ? s_pause_req : 1'b0;
    assign m_pause = PAUSE_ENABLE ? m_pause_req : 1'b0;

    // S domain: input to FIFO
    assign s_data_to_fifo = s_axis_tdata;
    assign s_keep_to_fifo = S_KEEP_ENABLE ? s_axis_tkeep : {S_KEEP_WIDTH{1'b0}};
    assign s_tlast_to_fifo = s_axis_tlast;
    assign s_tid_to_fifo = ID_ENABLE ? s_axis_tid : {ID_WIDTH{1'b0}};
    assign s_tdest_to_fifo = DEST_ENABLE ? s_axis_tdest : {DEST_WIDTH{1'b0}};
    assign s_tuser_to_fifo = USER_ENABLE ? s_axis_tuser : {USER_WIDTH{1'b0}};

    // S domain: write enable
    wire s_wr_allowed;
    assign s_wr_allowed = !s_full && !s_pause;
    assign s_wr_en = s_axis_tvalid && s_wr_allowed;

    // M domain: read enable
    wire m_rd_allowed;
    assign m_rd_allowed = !m_empty && !m_pause;
    assign m_rd_en = m_valid_out && m_axis_tready && m_rd_allowed;

    // Async FIFO
    axis_async_fifo #(
        .DEPTH(DEPTH),
        .DATA_WIDTH(S_DATA_WIDTH),
        .KEEP_ENABLE(S_KEEP_ENABLE),
        .KEEP_WIDTH(S_KEEP_WIDTH),
        .ID_ENABLE(ID_ENABLE),
        .ID_WIDTH(ID_WIDTH),
        .DEST_ENABLE(DEST_ENABLE),
        .DEST_WIDTH(DEST_WIDTH),
        .USER_ENABLE(USER_ENABLE),
        .USER_WIDTH(USER_WIDTH),
        .RAM_PIPELINE(RAM_PIPELINE)
    ) u_async_fifo (
        .s_clk(s_clk),
        .s_rst(s_rst),
        .s_wr_en(s_wr_en),
        .s_wr_data(s_data_to_fifo),
        .s_wr_keep(s_keep_to_fifo),
        .s_wr_tlast(s_tlast_to_fifo),
        .s_wr_tid(s_tid_to_fifo),
        .s_wr_tdest(s_tdest_to_fifo),
        .s_wr_tuser(s_tuser_to_fifo),
        .s_full(s_full),
        .s_overflow(s_overflow),
        .s_bad_frame(s_bad_frame),
        .s_good_frame(s_good_frame),
        .s_depth(s_depth),
        .s_depth_commit(s_depth_commit),
        .m_clk(m_clk),
        .m_rst(m_rst),
        .m_rd_en(m_rd_en),
        .m_rd_data(fifo_out_data),
        .m_rd_keep(fifo_out_keep),
        .m_rd_tlast(fifo_out_tlast),
        .m_rd_tid(fifo_out_tid),
        .m_rd_tdest(fifo_out_tdest),
        .m_rd_tuser(fifo_out_tuser),
        .m_empty(m_empty),
        .m_overflow(m_overflow),
        .m_bad_frame(m_bad_frame),
        .m_good_frame(m_good_frame),
        .m_depth(m_depth),
        .m_depth_commit(m_depth_commit)
    );

    // Width adapter
    axis_width_adapter #(
        .S_DATA_WIDTH(S_DATA_WIDTH),
        .S_KEEP_ENABLE(S_KEEP_ENABLE),
        .S_KEEP_WIDTH(S_KEEP_WIDTH),
        .M_DATA_WIDTH(M_DATA_WIDTH),
        .M_KEEP_ENABLE(M_KEEP_ENABLE),
        .M_KEEP_WIDTH(M_KEEP_WIDTH),
        .ID_ENABLE(ID_ENABLE),
        .ID_WIDTH(ID_WIDTH),
        .DEST_ENABLE(DEST_ENABLE),
        .DEST_WIDTH(DEST_WIDTH),
        .USER_ENABLE(USER_ENABLE),
        .USER_WIDTH(USER_WIDTH),
        .OUTPUT_FIFO_ENABLE(OUTPUT_FIFO_ENABLE),
        .FRAME_FIFO(FRAME_FIFO),
        .USER_BAD_FRAME_VALUE(USER_BAD_FRAME_VALUE),
        .USER_BAD_FRAME_MASK(USER_BAD_FRAME_MASK),
        .DROP_OVERSIZE_FRAME(DROP_OVERSIZE_FRAME),
        .DROP_BAD_FRAME(DROP_BAD_FRAME),
        .DROP_WHEN_FULL(DROP_WHEN_FULL),
        .MARK_WHEN_FULL(MARK_WHEN_FULL),
        .FRAME_PAUSE(FRAME_PAUSE)
    ) u_width_adapter (
        .clk(m_clk),
        .rst(m_rst),
        .s_valid(!m_empty),
        .s_data(fifo_out_data),
        .s_keep(fifo_out_keep),
        .s_tlast(fifo_out_tlast),
        .s_tid(fifo_out_tid),
        .s_tdest(fifo_out_tdest),
        .s_tuser(fifo_out_tuser),
        .s_ready(m_rd_en),
        .m_valid(m_valid_out),
        .m_data(m_data_out),
        .m_keep(m_keep_out),
        .m_tlast(m_tlast_out),
        .m_tid(m_tid_out),
        .m_tdest(m_tdest_out),
        .m_tuser(m_tuser_out),
        .m_ready(m_axis_tready)
    );

    // Pause active signals
    reg s_pause_active_reg;
    reg m_pause_active_reg;

    always @(posedge s_clk or posedge s_rst) begin
        if (s_rst)
            s_pause_active_reg <= 1'b0;
        else
            s_pause_active_reg <= s_pause;
    end

    always @(posedge m_clk or posedge m_rst) begin
        if (m_rst)
            m_pause_active_reg <= 1'b0;
        else
            m_pause_active_reg <= m_pause;
    end

    assign s_pause_active = s_pause_active_reg;
    assign m_pause_active = m_pause_active_reg;

endmodule

module axis_async_fifo #(
    parameter DEPTH = 4096,
    parameter DATA_WIDTH = 8,
    parameter KEEP_ENABLE = 0,
    parameter KEEP_WIDTH = 1,
    parameter ID_ENABLE = 0,
    parameter ID_WIDTH = 8,
    parameter DEST_ENABLE = 0,
    parameter DEST_WIDTH = 8,
    parameter USER_ENABLE = 0,
    parameter USER_WIDTH = 1,
    parameter RAM_PIPELINE = 1
)
(
    input  wire                     s_clk,
    input  wire                     s_rst,
    input  wire                     s_wr_en,
    input  wire [DATA_WIDTH-1:0]    s_wr_data,
    input  wire [KEEP_WIDTH-1:0]    s_wr_keep,
    input  wire                     s_wr_tlast,
    input  wire [ID_WIDTH-1:0]      s_wr_tid,
    input  wire [DEST_WIDTH-1:0]    s_wr_tdest,
    input  wire [USER_WIDTH-1:0]    s_wr_tuser,
    output wire                     s_full,
    output wire                     s_overflow,
    output wire                     s_bad_frame,
    output wire                     s_good_frame,
    output wire [$clog2(DEPTH):0]   s_depth,
    output wire [$clog2(DEPTH):0]   s_depth_commit,
    input  wire                     m_clk,
    input  wire                     m_rst,
    input  wire                     m_rd_en,
    output wire [DATA_WIDTH-1:0]    m_rd_data,
    output wire [KEEP_WIDTH-1:0]    m_rd_keep,
    output wire                     m_rd_tlast,
    output wire [ID_WIDTH-1:0]      m_rd_tid,
    output wire [DEST_WIDTH-1:0]    m_rd_tdest,
    output wire [USER_WIDTH-1:0]    m_rd_tuser,
    output wire                     m_empty,
    output wire                     m_overflow,
    output wire                     m_bad_frame,
    output wire                     m_good_frame,
    output wire [$clog2(DEPTH):0]   m_depth,
    output wire [$clog2(DEPTH):0]   m_depth_commit
);

    localparam ADDR_WIDTH = $clog2(DEPTH);
    localparam PTR_WIDTH = ADDR_WIDTH + 1;
    localparam DEPTH_MASK = DEPTH - 1;

    // Write pointer (S domain)
    reg [PTR_WIDTH-1:0] s_wr_ptr;
    reg [PTR_WIDTH-1:0] s_wr_ptr_gray;
    reg [PTR_WIDTH-1:0] s_wr_ptr_gray_sync;

    // Read pointer (M domain)
    reg [PTR_WIDTH-1:0] m_rd_ptr;
    reg [PTR_WIDTH-1:0] m_rd_ptr_gray;
    reg [PTR_WIDTH-1:0] m_rd_ptr_gray_sync;

    // RAM
    reg [DATA_WIDTH-1:0] ram_data [0:DEPTH-1];
    reg [KEEP_WIDTH-1:0] ram_keep [0:DEPTH-1];
    reg                  ram_tlast [0:DEPTH-1];
    reg [ID_WIDTH-1:0]   ram_tid [0:DEPTH-1];
    reg [DEST_WIDTH-1:0] ram_tdest [0:DEPTH-1];
    reg [USER_WIDTH-1:0] ram_tuser [0:DEPTH-1];

    // Write logic (S domain)
    always @(posedge s_clk or posedge s_rst) begin
        if (s_rst) begin
            s_wr_ptr <= {PTR_WIDTH{1'b0}};
            s_wr_ptr_gray <= {PTR_WIDTH{1'b0}};
        end else if (s_wr_en) begin
            s_wr_ptr <= s_wr_ptr + 1'b1;
            s_wr_ptr_gray <= s_wr_ptr ^ (s_wr_ptr >> 1);
        end
    end

    // Write to RAM
    always @(posedge s_clk) begin
        if (s_wr_en) begin
            ram_data[s_wr_ptr[ADDR_WIDTH-1:0]] <= s_wr_data;
            ram_keep[s_wr_ptr[ADDR_WIDTH-1:0]] <= s_wr_keep;
            ram_tlast[s_wr_ptr[ADDR_WIDTH-1:0]] <= s_wr_tlast;
            ram_tid[s_wr_ptr[ADDR_WIDTH-1:0]] <= s_wr_tid;
            ram_tdest[s_wr_ptr[ADDR_WIDTH-1:0]] <= s_wr_tdest;
            ram_tuser[s_wr_ptr[ADDR_WIDTH-1:0]] <= s_wr_tuser;
        end
    end

    // Read pointer (M domain)
    always @(posedge m_clk or posedge m_rst) begin
        if (m_rst) begin
            m_rd_ptr <= {PTR_WIDTH{1'b0}};
            m_rd_ptr_gray <= {PTR_WIDTH{1'b0}};
        end else if (m_rd_en) begin
            m_rd_ptr <= m_rd_ptr + 1'b1;
            m_rd_ptr_gray <= m_rd_ptr ^ (m_rd_ptr >> 1);
        end
    end

    // Read from RAM
    wire [ADDR_WIDTH-1:0] m_rd_addr = m_rd_ptr[ADDR_WIDTH-1:0];
    assign m_rd_data = ram_data[m_rd_addr];
    assign m_rd_keep = ram_keep[m_rd_addr];
    assign m_rd_tlast = ram_tlast[m_rd_addr];
    assign m_rd_tid = ram_tid[m_rd_addr];
    assign m_rd_tdest = ram_tdest[m_rd_addr];
    assign m_rd_tuser = ram_tuser[m_rd_addr];

    // Synchronize write pointer to M domain
    reg [PTR_WIDTH-1:0] s_wr_ptr_gray_sync1;
    reg [PTR_WIDTH-1:0] s_wr_ptr_gray_sync2;

    always @(posedge m_clk or posedge m_rst) begin
        if (m_rst) begin
            s_wr_ptr_gray_sync1 <= {PTR_WIDTH{1'b0}};
            s_wr_ptr_gray_sync2 <= {PTR_WIDTH{1'b0}};
        end else begin
            s_wr_ptr_gray_sync1 <= s_wr_ptr_gray;
            s_wr_ptr_gray_sync2 <= s_wr_ptr_gray_sync1;
        end
    end

    // Synchronize read pointer to S domain
    reg [PTR_WIDTH-1:0] m_rd_ptr_gray_sync1;
    reg [PTR_WIDTH-1:0] m_rd_ptr_gray_sync2;

    always @(posedge s_clk or posedge s_rst) begin
        if (s_rst) begin
            m_rd_ptr_gray_sync1 <= {PTR_WIDTH{1'b0}};
            m_rd_ptr_gray_sync2 <= {PTR_WIDTH{1'b0}};
        end else begin
            m_rd_ptr_gray_sync1 <= m_rd_ptr_gray;
            m_rd_ptr_gray_sync2 <= m_rd_ptr_gray_sync1;
        end
    end

    // Convert gray to binary
    function [PTR_WIDTH-1:0] gray_to_binary;
        input [PTR_WIDTH-1:0] gray;
        integer i;
        begin
            gray_to_binary[PTR_WIDTH-1] = gray[PTR_WIDTH-1];
            for (i = PTR_WIDTH-2; i >= 0; i = i - 1)
                gray_to_binary[i] = gray_to_binary[i+1] ^ gray[i];
        end
    endfunction

    wire [PTR_WIDTH-1:0] s_wr_ptr_bin_m = gray_to_binary(s_wr_ptr_gray_sync2);
    wire [PTR_WIDTH-1:0] m_rd_ptr_bin_s = gray_to_binary(m_rd_ptr_gray_sync2);

    // Full and empty
    assign s_full = (s_wr_ptr_gray_sync2 == m_rd_ptr_gray_sync2) && (s_wr_ptr[PTR_WIDTH-1] != m_rd_ptr_bin_s[PTR_WIDTH-1]);
    assign m_empty = (s_wr_ptr_gray_sync2 == m_rd_ptr_gray_sync2) && (m_rd_ptr[PTR_WIDTH-1] != s_wr_ptr_bin_m[PTR_WIDTH-1]);

    // Depth calculation
    wire [$clog2(DEPTH):0] s_depth_calc = s_wr_ptr - m_rd_ptr_bin_s;
    wire [$clog2(DEPTH):0] m_depth_calc = s_wr_ptr_bin_m - m_rd_ptr;

    assign s_depth = s_depth_calc;
    assign m_depth = m_depth_calc;
    assign s_depth_commit = s_depth_calc;
    assign m_depth_commit = m_depth_calc;

    // Status signals (simplified)
    assign s_overflow = 1'b0;
    assign m_overflow = 1'b0;
    assign s_bad_frame = 1'b0;
    assign m_bad_frame = 1'b0;
    assign s_good_frame = 1'b0;
    assign m_good_frame = 1'b0;

endmodule

module axis_width_adapter #(
    parameter S_DATA_WIDTH = 8,
    parameter S_KEEP_ENABLE = 0,
    parameter S_KEEP_WIDTH = 1,
    parameter M_DATA_WIDTH = 8,
    parameter M_KEEP_ENABLE = 0,
    parameter M_KEEP_WIDTH = 1,
    parameter ID_ENABLE = 0,
    parameter ID_WIDTH = 8,
    parameter DEST_ENABLE = 0,
    parameter DEST_WIDTH = 8,
    parameter USER_ENABLE = 0,
    parameter USER_WIDTH = 1,
    parameter OUTPUT_FIFO_ENABLE = 0,
    parameter FRAME_FIFO = 0,
    parameter USER_BAD_FRAME_VALUE = 1'b1,
    parameter USER_BAD_FRAME_MASK = 1'b1,
    parameter DROP_OVERSIZE_FRAME = 0,
    parameter DROP_BAD_FRAME = 0,
    parameter DROP_WHEN_FULL = 0,
    parameter MARK_WHEN_FULL = 0,
    parameter FRAME_PAUSE = 0
)
(
    input  wire                     clk,
    input  wire                     rst,
    input  wire                     s_valid,
    input  wire [S_DATA_WIDTH-1:0]  s_data,
    input  wire [S_KEEP_WIDTH-1:0]  s_keep,
    input  wire                     s_tlast,
    input  wire [ID_WIDTH-1:0]      s_tid,
    input  wire [DEST_WIDTH-1:0]    s_tdest,
    input  wire [USER_WIDTH-1:0]    s_tuser,
    output wire                     s_ready,
    output wire                     m_valid,
    output wire [M_DATA_WIDTH-1:0]  m_data,
    output wire [M_KEEP_WIDTH-1:0]  m_keep,
    output wire                     m_tlast,
    output wire [ID_WIDTH-1:0]      m_tid,
    output wire [DEST_WIDTH-1:0]    m_tdest,
    output wire [USER_WIDTH-1:0]    m_tuser,
    input  wire                     m_ready
);

    // Simple pass-through for now (width adapter logic would go here)
    // For this implementation, we assume S_DATA_WIDTH == M_DATA_WIDTH
    // or handle the conversion with a simple buffer

    reg [S_DATA_WIDTH-1:0] data_buf;
    reg [S_KEEP_WIDTH-1:0] keep_buf;
    reg tlast_buf;
    reg [ID_WIDTH-1:0] tid_buf;
    reg [DEST_WIDTH-1:0] tdest_buf;
    reg [USER_WIDTH-1:0] tuser_buf;
    reg valid_buf;

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            valid_buf <= 1'b0;
            data_buf <= {S_DATA_WIDTH{1'b0}};
            keep_buf <= {S_KEEP_WIDTH{1'b0}};
            tlast_buf <= 1'b0;
            tid_buf <= {ID_WIDTH{1'b0}};
            tdest_buf <= {DEST_WIDTH{1'b0}};
            tuser_buf <= {USER_WIDTH{1'b0}};
        end else begin
            if (s_valid && s_ready) begin
                data_buf <= s_data;
                keep_buf <= s_keep;
                tlast_buf <= s_tlast;
                tid_buf <= s_tid;
                tdest_buf <= s_tdest;
                tuser_buf <= s_tuser;
                valid_buf <= 1'b1;
            end else if (m_valid && m_ready) begin
                valid_buf <= 1'b0;
            end
        end
    end

    assign s_ready = !valid_buf || (m_valid && m_ready);
    assign m_valid = valid_buf;
    assign m_data = data_buf[S_DATA_WIDTH-1:0] & {M_DATA_WIDTH{1'b1}};
    assign m_keep = keep_buf[S_KEEP_WIDTH-1:0] & {M_KEEP_WIDTH{1'b1}};
    assign m_tlast = tlast_buf;
    assign m_tid = tid_buf;
    assign m_tdest = tdest_buf;
    assign m_tuser = tuser_buf;

endmodule
